180	async function acquireStoreLock(paths: StorePaths): Promise<() => Promise<void>> {
181	  const deadline = Date.now() + STORE_LOCK_TIMEOUT_MS;
182	  while (true) {
183	    try {
184	      await mkdir(paths.lock, { mode: 0o700 });
185	      try {
186	        await writePrivateJson(join(paths.lock, "owner.json"), { pid: process.pid });
187	      } catch (error) {
188	        await rm(paths.lock, { recursive: true, force: true });
189	        throw error;
190	      }
191	      return async () => rm(paths.lock, { recursive: true, force: true });
192	    } catch (error) {
193	      if (!isNodeError(error) || error.code !== "EEXIST") throw error;
194	      try {
195	        const lockStat = await stat(paths.lock);
196	        if (Date.now() - lockStat.mtimeMs > STORE_LOCK_STALE_MS) {
197	          let ownerAlive = false;
198	          try {
199	            const owner = JSON.parse(await readFile(join(paths.lock, "owner.json"), "utf8")) as { pid?: unknown };
200	            if (typeof owner.pid === "number" && Number.isInteger(owner.pid) && owner.pid > 0) {
201	              try {
202	                process.kill(owner.pid, 0);
203	                ownerAlive = true;
204	              } catch (probeError) {
205	                ownerAlive = isNodeError(probeError) && probeError.code === "EPERM";
206	              }
207	            }
208	          } catch {
209	            // A stale lock without a readable live owner is abandoned publication state.
210	          }
211	          if (!ownerAlive) {
212	            await rm(paths.lock, { recursive: true, force: true });
213	            continue;
214	          }
215	        }
216	      } catch (statError) {
217	        if (!isNodeError(statError) || statError.code !== "ENOENT") throw statError;
218	      }
219	      if (Date.now() >= deadline) {
220	        throw new ToolResultError("TOOL_RESULT_STORE_BUSY", "Tool-result store publication lock timed out");
221	      }
222	      await sleep(LOCK_RETRY_MS);
